selector_to_html = {"a[href=\"hw01.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Homework 1<a class=\"headerlink\" href=\"#homework-1\" title=\"Link to this heading\">#</a></h1><p><strong>Due:</strong> Thursday, August 27, 2026 23:58<span class=\"semantic-line-break\"></span><strong>Submit:</strong> Gradescope, through\n<a class=\"reference external\" href=\"https://learn.uark.edu/ultra/courses/_529368_1/outline/\">Blackboard\u2019s assignment area</a>.</p><p>Please write your homework by hand. Start each exercise on a new page, scan\nyour work to a legible PDF, and clearly mark the pages associated with every\nexercise.</p>", "a[href=\"hw03.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Homework 3<a class=\"headerlink\" href=\"#homework-3\" title=\"Link to this heading\">#</a></h1><p><strong>Due:</strong> Thursday, September 17, 2026 23:58<span class=\"semantic-line-break\"></span><strong>Submit:</strong> Gradescope, through\n<a class=\"reference external\" href=\"https://learn.uark.edu/ultra/courses/_529368_1/outline/\">Blackboard\u2019s assignment area</a>.</p><p>Please write your homework by hand. Start each exercise on a new page, scan\nyour work to a legible PDF, and clearly mark the pages associated with every\nexercise.</p>", "a[href=\"#written-homework\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Written homework<a class=\"headerlink\" href=\"#written-homework\" title=\"Link to this heading\">#</a></h2><p>Submit your work through Gradescope using\n<a class=\"reference external\" href=\"https://learn.uark.edu/ultra/courses/_529368_1/outline/\">Blackboard\u2019s assignment area</a>. The\nprintable version is available from each assignment page.</p><p>Weekly homework gives you a chance to work through more involved problems using\nthe techniques we have learned. A complete solution includes both a clear\nexplanation and correct computations. Every exercise is required; point values\nindicate how much each exercise contributes to the assignment grade.</p>", "a[href=\"#academic-integrity-collaboration-and-artificial-intelligence\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Academic integrity, collaboration, and artificial intelligence<a class=\"headerlink\" href=\"#academic-integrity-collaboration-and-artificial-intelligence\" title=\"Link to this heading\">#</a></h2><p>You are encouraged to work with classmates, tutors, and me: talking through\nideas, definitions, and problem-solving strategies is a valuable part of\nlearning. You must understand every solution you submit and write it based on\nyour own understanding. Please do not copy another person\u2019s solution or\nwrite-up.</p><p>You may use generative artificial intelligence as a study aid, but not to\nproduce any work that you submit for credit. It is fine to ask a study question\nsuch as, ``I do not understand when to use generating functions to count\ncombinations with restrictions.\u2019\u2019 It is not acceptable to ask an AI system how\nto solve a specific assigned problem. Rephrasing a generated solution using\nyour own words is not acceptable. If you are unsure whether a particular use is\nallowed, ask me before you submit your work.</p>", "a[href=\"#online-questions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Online questions<a class=\"headerlink\" href=\"#online-questions\" title=\"Link to this heading\">#</a></h2><p>Online questions usually follow each lecture and are due at the start of our\nnext class meeting. They are available through\n<a class=\"reference external\" href=\"https://learn.uark.edu/ultra/courses/_529368_1/outline/\">Blackboard\u2019s online-question area</a>;\ndeadlines appear in the <a class=\"reference external\" href=\"https://learn.uark.edu/ultra/courses/_529368_1/calendar/\">Blackboard\nCalendar</a>.</p><p>Online questions provide a quick chance to practice vocabulary and core skills\nbefore we build on the material. Most questions allow multiple attempts.</p>", "a[href=\"hw02.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Homework 2<a class=\"headerlink\" href=\"#homework-2\" title=\"Link to this heading\">#</a></h1><p><strong>Due:</strong> Thursday, September 3, 2026 23:58<span class=\"semantic-line-break\"></span><strong>Submit:</strong> Gradescope, through\n<a class=\"reference external\" href=\"https://learn.uark.edu/ultra/courses/_529368_1/outline/\">Blackboard\u2019s assignment area</a>.</p><p>Please write your homework by hand. Start each exercise on a new page, scan\nyour work to a legible PDF, and clearly mark the pages associated with every\nexercise.</p>", "a[href=\"#assignments\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Assignments<a class=\"headerlink\" href=\"#assignments\" title=\"Link to this heading\">#</a></h1><h2>Written homework<a class=\"headerlink\" href=\"#written-homework\" title=\"Link to this heading\">#</a></h2><p>Submit your work through Gradescope using\n<a class=\"reference external\" href=\"https://learn.uark.edu/ultra/courses/_529368_1/outline/\">Blackboard\u2019s assignment area</a>. The\nprintable version is available from each assignment page.</p><p>Weekly homework gives you a chance to work through more involved problems using\nthe techniques we have learned. A complete solution includes both a clear\nexplanation and correct computations. Every exercise is required; point values\nindicate how much each exercise contributes to the assignment grade.</p>", "a[href=\"example-homework-writeup.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Example Homework Write-Ups<a class=\"headerlink\" href=\"#example-homework-write-ups\" title=\"Link to this heading\">#</a></h1><p>This page shows what a complete handwritten homework solution should look like.\nThe goal is not a long proof. For each exercise, write at least one sentence\nthat explains your approach, and give word labels to the quantities in your\ncalculation.</p><p>The model solutions are set in larger, handwriting-like type to suggest the\namount of work that you could reasonably write by hand.</p>"}
skip_classes = ["headerlink", "sd-stretched-link", "no-hover-preview"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`article.bd-article ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
